files.normalizer.py:
"""Data normalization utilities."""
from config import DEFAULT_NORMALIZE


def normalize(values: list, enabled: bool = DEFAULT_NORMALIZE) -> list:
    """Normalize values to [0, 1] range if enabled."""
    if not enabled:
        return values
    if not values:
        return values
    min_v = min(values)
    max_v = max(values)
    if max_v == min_v:
        return [0.5] * len(values)
    return [(v - min_v) / (max_v - min_v) for v in values]

files.stats.py:
"""Statistics helpers."""


def mean(values: list) -> float:
    if not values:
        return 0.0
    return sum(values) / len(values)


def count_above(values: list, threshold: float) -> int:
    return sum(1 for v in values if v > threshold)
